  // is virtualized, so this bounds heap rather than rendered nodes.
  var HIL_PACKET_RETAIN_LIMIT = 20000;
	  var HIL_PACKET_RENDER_LIMIT = 750;
	  var HIL_PACKET_VIRTUAL_ROW_HEIGHT = 26;
	  var HIL_PACKET_VIRTUAL_OVERSCAN = 16;
