    if (lcsi === 0x03) return "initialisation state";
    if ((lcsi & 0x0C) === 0x0C) return "termination state";
    if ((lcsi & 0x0D) === 0x05) return "operational - activated";
    if ((lcsi & 0x0D) === 0x04) return "operational - deactivated";
