    "ef-spn":         _SAIP_WIZARD_SPN,
    "ef-ust":         _SAIP_WIZARD_UST,
    "ef-pl":          _SAIP_WIZARD_PL,
    "ef-li":          _SAIP_WIZARD_LI,
    "ef-fplmn":       _SAIP_WIZARD_FPLMN,
    "ef-ehplmn":      _SAIP_WIZARD_EHPLMN,
    "ef-plmnwact":    _SAIP_WIZARD_PLMNWACT,
    "ef-oplmnwact":   _SAIP_WIZARD_OPLMNWACT,
